const W = 9900;              // ширина таблиц, DXA
const GREY = 'EFEFEF';
const LIGHT = 'F7F7F7';

const P = (t, o = {}) => new Paragraph({
  spacing: { after: o.after === undefined ? 120 : o.after, line: 264 },
  alignment: o.align,
  indent: o.indent,
  children: [new TextRun({ text: t, bold: o.b, italics: o.i, size: o.size || 20, color: o.color })]
});

const RICH = (runs, o = {}) => new Paragraph({
  spacing: { after: o.after === undefined ? 120 : o.after, line: 264 },
  children: runs.map(r => new TextRun({ text: r[0], bold: r[1] === 'b', italics: r[1] === 'i', size: 20 }))
});

const H1 = t => new Paragraph({ text: t, heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 160 } });
const H2 = t => new Paragraph({ text: t, heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 120 } });
const H3 = t => new Paragraph({ text: t, heading: HeadingLevel.HEADING_3, spacing: { before: 200, after: 100 } });

const BUL = t => new Paragraph({
  numbering: { reference: 'bul', level: 0 },
  spacing: { after: 80, line: 264 },
  children: [new TextRun({ text: t, size: 20 })]
});

const NUM = t => new Paragraph({
  numbering: { reference: 'num', level: 0 },
  spacing: { after: 80, line: 264 },
  children: [new TextRun({ text: t, size: 20 })]
});

function cell(text, w, o = {}) {
  const parts = Array.isArray(text) ? text : [text];
  return new TableCell({
    width: { size: w, type: WidthType.DXA },
    shading: o.shade ? { type: ShadingType.CLEAR, fill: o.shade, color: 'auto' } : undefined,
    margins: { top: 60, bottom: 60, left: 90, right: 90 },
    verticalAlign: 'center',
    columnSpan: o.span,
    children: parts.map((t, i) => new Paragraph({
      spacing: { after: i === parts.length - 1 ? 0 : 60, line: 240 },
      alignment: o.align,
      children: [new TextRun({ text: String(t), bold: o.b, italics: o.i, size: o.size || 18 })]
    }))
  });
}

// rows: массив массивов; widths: массив ширин; opts.headerRows
function TBL(widths, rows, opts = {}) {
  const trs = rows.map((r, ri) => {
    const isHead = ri < (opts.headerRows === undefined ? 1 : opts.headerRows);
    const isSection = opts.sections && opts.sections.includes(ri);
    return new TableRow({
      tableHeader: isHead,
      children: r.map((c, ci) => {
        if (c === null) return null;
        const span = (isSection && ci === 0) ? widths.length : undefined;
        const w = span ? widths.reduce((a, b) => a + b, 0) : widths[ci];
        return cell(c, w, {
          b: isHead || isSection,
          shade: isHead ? GREY : (isSection ? LIGHT : undefined),
          align: (opts.rightCols && opts.rightCols.includes(ci) && !isSection) ? AlignmentType.RIGHT : undefined
        });
      }).filter(Boolean)
    });
  });
  return new Table({
    width: { size: widths.reduce((a, b) => a + b, 0), type: WidthType.DXA },
    columnWidths: widths,
    rows: trs
  });
}

