/* ============================ 6. ГИПОТЕЗЫ ============================ */
const hyp = (code, title, obs, question, variants, check, impact) => {
  const out = [H2(code + '. ' + title)];
  out.push(RICH([['Наблюдение. ', 'b'], [obs]]));
  out.push(RICH([['Основной вопрос. ', 'b'], [question]]));
  variants.forEach(v => out.push(BUL(v)));
  out.push(RICH([['Проверка. ', 'b'], [check]]));
  out.push(RICH([['Последствие для задачи. ', 'b'], [impact]]));
  return out;
};

